"use client";
import { Button } from "./button";
import { Slider } from "./slider";
import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
  type HTMLAttributes,
  type CSSProperties,
} from "react";
import "./voice-player.css";

export type PlaybackGroup = Set<() => void>;
export const createPlaybackGroup = (): PlaybackGroup => new Set();
interface PlaybackState {
  playing: boolean;
  time: number;
  duration: number;
  rate: number;
  error: string;
  available: boolean;
  toggle: () => void;
  seek: (time: number) => void;
  setRate: (rate: number) => void;
}
const PlaybackContext = createContext<PlaybackState | null>(null);
export function useVoicePlayer() {
  const value = useContext(PlaybackContext);
  if (!value) throw new Error("Voice controls must be inside VoicePlayerRoot.");
  return value;
}
export interface VoicePlayerRootProps extends HTMLAttributes<HTMLDivElement> {
  src?: string;
  group?: PlaybackGroup;
  children: ReactNode;
  onPlaybackChange?: (playing: boolean) => void;
}
/** React owns the controls and audio element. Media state stays with that element.
 * Consumers can compose these controls or supply their own with useVoicePlayer. */
export function VoicePlayerRoot({
  src,
  group,
  children,
  onPlaybackChange,
  className = "",
  ...props
}: VoicePlayerRootProps) {
  const audio = useRef<HTMLAudioElement>(null);
  const [state, setState] = useState({
    playing: false,
    time: 0,
    duration: 0,
    rate: 1,
    error: "",
  });
  const callback = useRef(onPlaybackChange);
  callback.current = onPlaybackChange;
  const sync = () => {
    const a = audio.current;
    if (a)
      setState((s) => ({
        ...s,
        playing: !a.paused,
        time: a.currentTime,
        duration: Number.isFinite(a.duration) ? a.duration : 0,
        rate: a.playbackRate,
      }));
  };
  useEffect(() => {
    const a = audio.current!;
    const pause = () => a.pause();
    group?.add(pause);
    return () => {
      pause();
      group?.delete(pause);
    };
  }, [group]);
  useEffect(() => {
    setState({ playing: false, time: 0, duration: 0, rate: 1, error: "" });
  }, [src]);
  const fail = (error?: unknown) => {
    const name = error instanceof Error ? error.name : "";
    const message =
      name === "NotAllowedError"
        ? "Playback blocked. Press play to retry."
        : audio.current?.error?.code === 2
          ? "Unable to load audio. Press play to retry."
          : "Audio unavailable. Check the source and try again.";
    setState((s) => ({ ...s, error: message }));
  };
  const toggle = async () => {
    const a = audio.current;
    if (!a || !src) return;
    if (!a.paused) {
      a.pause();
      return;
    }
    setState((s) => ({ ...s, error: "" }));
    group?.forEach((pause) => pause());
    if (a.error) a.load();
    try {
      await a.play();
    } catch (error) {
      fail(error);
    }
  };
  return (
    <PlaybackContext.Provider
      value={{
        ...state,
        available: !!src,
        toggle,
        seek: (time) => {
          const a = audio.current;
          if (a && state.duration) {
            a.currentTime = Math.max(0, Math.min(state.duration, time));
            sync();
          }
        },
        setRate: (rate) => {
          if (audio.current) {
            audio.current.playbackRate = rate;
            sync();
          }
        },
      }}
    >
      <div
        {...props}
        className={`roc-voice ${className}`}
        data-state={
          state.error
            ? "error"
            : state.playing
              ? "playing"
              : src
                ? "ready"
                : "empty"
        }
      >
        <audio
          ref={audio}
          src={src}
          preload="metadata"
          hidden
          onPlay={() => {
            sync();
            callback.current?.(true);
          }}
          onPause={() => {
            sync();
            callback.current?.(false);
          }}
          onEnded={sync}
          onTimeUpdate={sync}
          onDurationChange={sync}
          onLoadedMetadata={sync}
          onRateChange={sync}
          onError={() => fail()}
        />
        {children}
        {state.error && (
          <span className="roc-voice-error" role="alert">
            {state.error}
          </span>
        )}
      </div>
    </PlaybackContext.Provider>
  );
}
const timeLabel = (seconds: number) =>
  `${Math.floor(seconds / 60)}:${String(Math.floor(seconds % 60)).padStart(2, "0")}`;
export function VoicePlayButton() {
  const s = useVoicePlayer();
  return (
    <Button variant="ghost" size="sm"
      type="button"
      className="roc-voice-play"
      aria-label={s.playing ? "Pause audio" : "Play audio"}
      disabled={!s.available}
      onClick={s.toggle}
    >
      <span
        aria-hidden="true"
        className="roc-voice-glyph"
        data-state={s.playing ? "inactive" : "active"}
      >
        ▶
      </span>
      <span
        aria-hidden="true"
        className="roc-voice-glyph"
        data-state={s.playing ? "active" : "inactive"}
      >
        Ⅱ
      </span>
    </Button>
  );
}
export function VoiceSeek() {
  const s = useVoicePlayer();
  return (
    <Slider
      className="roc-voice-seek"
      aria-label="Playback position"
      getValueText={value => `${timeLabel(value)} of ${timeLabel(s.duration)}`}
      min={0}
      max={s.duration || 1}
      step={0.01}
      value={[s.time]}
      disabled={!s.duration}
      onValueChange={value => s.seek(Array.isArray(value) ? value[0] : value)}
    />
  );
}
export function VoiceTime() {
  const s = useVoicePlayer();
  return (
    <span className="roc-voice-time">
      {s.available ? timeLabel(s.time || s.duration) : "No audio"}
    </span>
  );
}
export function VoiceRate({ rates = [1, 1.5, 2] }: { rates?: number[] }) {
  const s = useVoicePlayer();
  return (
    <Button variant="ghost" size="sm"
      type="button"
      className="roc-voice-rate"
      aria-label={`Playback speed, ${s.rate} times`}
      disabled={!s.available || !rates.length}
      onClick={() =>
        s.setRate(rates[(rates.indexOf(s.rate) + 1) % rates.length])
      }
    >
      {s.rate}×
    </Button>
  );
}
export interface VoicePlayerProps
  extends Omit<VoicePlayerRootProps, "children"> {
  label?: string;
}
export function VoicePlayer({
  label = "Audio player",
  ...props
}: VoicePlayerProps) {
  return (
    <VoicePlayerRoot role="group" aria-label={label} {...props}>
      <VoicePlayButton />
      <VoiceSeek />
      <VoiceTime />
      <VoiceRate />
    </VoicePlayerRoot>
  );
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Button as AnimatedButton } from "@animate-ui/react/primitives/buttons/button";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp: React.ElementType = AnimatedButton;

  return (
    <Comp
      asChild={asChild}
      tapScale={disabled || pending ? 1 : 0.97}
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

import "./button.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: var(--roc-space-2, 8px);
  min-height: var(--roc-control-height, 36px);
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-button-radius, var(--roc-radius-control));
  font-family: var(--roc-font-control, inherit);
  font-weight: var(--roc-weight-control, 500);
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--roc-motion-quick) ease-out,
    box-shadow var(--roc-motion-quick) ease-out;
}
/* Keep the shared .roc-ui font reset from changing text button height. */
.roc-ui.roc-ui-button {
  line-height: 1.2;
}
.roc-ui-button.roc-ui-button-variant-default {
  background: var(--roc-accent, var(--roc-ink, #252525));
  color: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
.roc-ui-button.roc-ui-button-variant-secondary {
  background: var(--roc-marker, #efefef);
}
.roc-ui-button.roc-ui-button-variant-destructive {
  background: #b73838;
  color: white;
}
.roc-ui-button.roc-ui-button-variant-outline {
  border-color: var(--roc-line, #dedede);
  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
/* Pending swaps the label in place: the outgoing text lifts away blurred while
   the incoming text settles up from below. */
.roc-ui-button-label > span {
  transition:
    opacity var(--roc-motion-quick) ease-in-out,
    transform var(--roc-motion-quick) ease-in-out,
    filter var(--roc-motion-quick) ease-in-out;
}
.roc-ui-button-label > span[data-state="inactive"] {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  pointer-events: none;
}
.roc-ui-button-label > span:first-child[data-state="inactive"] {
  transform: translateY(-4px);
}
.roc-ui-button-label > span:last-child[data-state="inactive"] {
  transform: translateY(4px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-button-label > span {
    transition: none;
  }
}

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-family: var(--roc-font-body, inherit);
  font-size: var(--roc-text-body, 13px);
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
"use client";

import * as React from "react";
import { cn } from "./utils";
import { Slider as SliderPrimitive } from "./primitive-slider";

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  thumbLabels,
  getValueText,
  "aria-label": ariaLabel,
  ...props
}: React.ComponentProps<typeof SliderPrimitive.Root> & {
  thumbLabels?: string[];
  /** Spoken value for a thumb, e.g. "640 pixels, sm". Defaults to the number. */
  getValueText?: (value: number, index: number) => string;
}) {
  const _values = React.useMemo(
    () =>
      Array.isArray(value)
        ? value
        : Array.isArray(defaultValue)
          ? defaultValue
          : [min, max],
    [value, defaultValue, min, max],
  );

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      className={cn("roc-ui", className)}
      // One thumb carries the label itself; a range labels the group.
      aria-label={_values.length > 1 ? ariaLabel : undefined}
      {...props}
    >
      <SliderPrimitive.Track data-slot="slider-track" className={cn("roc-ui")}>
        <SliderPrimitive.Range
          data-slot="slider-range"
          className={cn("roc-ui")}
        />
      </SliderPrimitive.Track>
      {Array.from({ length: _values.length }, (_, index) => (
        <SliderPrimitive.Thumb
          aria-label={
            thumbLabels?.[index] ??
            (_values.length === 1 ? ariaLabel : undefined)
          }
          aria-valuetext={getValueText?.(_values[index], index)}
          data-slot="slider-thumb"
          key={index}
          className="roc-ui"
        />
      ))}
    </SliderPrimitive.Root>
  );
}

export { Slider };

import "./slider.css";

"use client";
// ROC primitive: a draggable value or range. Behaviour from Base UI.
// Keeps ROC's markup (Track, Range and Thumbs as siblings) and adds the Control Base UI needs.
import * as React from "react";
import { Slider as Base } from "@animate-ui/react/primitives/base-ui/slider";

type RootProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange" | "dir"
> & {
  value?: number[];
  defaultValue?: number[];
  onValueChange?: (value: number[]) => void;
  /** Called when a drag or key press ends, with the final value. */
  onValueCommit?: (value: number[]) => void;
  min?: number;
  max?: number;
  step?: number;
  minStepsBetweenThumbs?: number;
  orientation?: "horizontal" | "vertical";
  disabled?: boolean;
  name?: string;
  form?: string;
  dir?: "ltr" | "rtl";
};

const asArray = (value: number | readonly number[]) =>
  Array.isArray(value) ? [...value] : [value as number];

type ThumbProps = Omit<React.ComponentProps<"div">, "ref"> & {
  index?: number;
  "aria-label"?: string;
  "aria-valuetext"?: string;
  ref?: React.Ref<any>;
};

function Root({
  value,
  defaultValue,
  onValueChange,
  onValueCommit,
  minStepsBetweenThumbs,
  dir: _dir,
  children,
  ...props
}: RootProps) {
  // Base UI needs each thumb's index; shadcn infers it from order.
  let next = 0;
  const numbered = React.Children.map(children, (child) =>
    React.isValidElement(child) && child.type === Thumb
      ? React.cloneElement(child as React.ReactElement<ThumbProps>, { index: next++ })
      : child,
  );
  return (
    <Base.Root
      {...(props as object)}
      value={value}
      defaultValue={defaultValue}
      onValueChange={(v: number | readonly number[]) => onValueChange?.(asArray(v))}
      onValueCommitted={(v: number | readonly number[]) => onValueCommit?.(asArray(v))}
      minStepsBetweenValues={minStepsBetweenThumbs}
      thumbAlignment="edge"
      // A dragged thumb may cross the other; values stay sorted.
      thumbCollisionBehavior="swap"
    >
      <Base.Control data-slot="slider-control">{numbered}</Base.Control>
    </Base.Root>
  );
}

function Thumb({
  "aria-label": label,
  "aria-valuetext": valueText,
  ...props
}: ThumbProps) {
  return (
    <Base.Thumb
      {...(props as object)}
      getAriaLabel={label ? () => label : undefined}
      getAriaValueText={valueText ? () => valueText : undefined}
    />
  );
}

export const Slider = {
  Root,
  Track: Base.Track as React.ComponentType<Omit<React.ComponentProps<"div">, "ref">>,
  Range: Base.Indicator as React.ComponentType<Omit<React.ComponentProps<"div">, "ref">>,
  Thumb,
};

@import "./ui-base.css";
.roc-ui[data-slot="slider"] {
  display: flex;
  align-items: center;
  position: relative;
  width: 100%;
  height: 36px;
  touch-action: none;
  user-select: none;
}
.roc-ui[data-slot="slider-track"] {
  position: relative;
  flex-grow: 1;
  height: 4px;
  border-radius: 99px;
  corner-shape: round;
  background: var(--roc-line, #e2e2e2);
  overflow: hidden;
}
.roc-ui[data-slot="slider-range"] {
  position: absolute;
  height: 100%;
  background: var(--roc-accent, var(--roc-ink, #252525));
}
.roc-ui[data-slot="slider-thumb"] {
  display: block;
  position: relative;
  width: 18px;
  height: 18px;
  border: 1px solid var(--roc-line, #bcbcbc);
  border-radius: 50%;
  corner-shape: round;
  background: var(--roc-paper, #fff);
  box-shadow: 0 1px 3px #0001;
}
.roc-ui[data-slot="slider-thumb"]::before {
  content: "";
  position: absolute;
  inset: -9px;
}
.roc-ui[data-slot="slider"][data-orientation="vertical"] {
  flex-direction: column;
  width: 36px;
  height: 180px;
}
.roc-ui[data-slot="slider-track"][data-orientation="vertical"] {
  width: 4px;
  height: 100%;
}
.roc-ui[data-slot="slider-range"][data-orientation="vertical"] {
  width: 100%;
}
/* Base UI nests the track and thumbs in a control that takes the pointer. */
.roc-ui[data-slot="slider"] > [data-slot="slider-control"] {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1;
  width: 100%;
  height: 100%;
}
.roc-ui[data-slot="slider"][data-orientation="vertical"] > [data-slot="slider-control"] {
  flex-direction: column;
}
/* The focusable element is the range input inside the thumb. */
.roc-ui[data-slot="slider-thumb"]:has(input:focus-visible) {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
@media (forced-colors: active) {
  .roc-ui[data-slot="slider-thumb"]:has(input:focus-visible) {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}

@import "./surface.css";
.roc-voice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  width: 100%;
  padding: 14px;
  background: var(--roc-paper, #fcfbf8);
  border: 1px solid var(--roc-line, #e3e1da);
  border-radius: var(--roc-radius, 12px);
}
.roc-voice button {
  border: 0;
  background: var(--roc-subtle, #eaece5);
  border-radius: 50%;
  corner-shape: round;
  min-width: 34px;
  height: 34px;
  font-size: 12px;
  flex: none;
}
.roc-voice .roc-voice-rate {
  border-radius: var(--roc-radius, 8px);
  background: transparent;
  min-width: 30px;
}
.roc-voice-seek {
  flex: 1;
  min-width: 20px;
  width: 0;
  accent-color: var(--roc-accent, #667e68);
  height: 3px;
}
.roc-voice-time {
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.roc-voice-error {
  flex-basis: 100%;
  font-size: 12px;
  line-height: 1.5;
  color: var(--roc-error, #9d4935);
}
.roc-voice button:disabled {
  opacity: 0.4;
}
/* Play and pause share one slot and cross-fade with a small blur and scale. */
.roc-voice .roc-voice-play {
  display: inline-grid;
  place-items: center;
}
.roc-voice-glyph {
  grid-area: 1 / 1;
  transition:
    opacity 250ms ease-in-out,
    transform 250ms ease-in-out,
    filter 250ms ease-in-out;
}
.roc-voice-glyph[data-state="inactive"] {
  opacity: 0;
  transform: scale(0.25);
  filter: blur(2px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-voice-glyph {
    transition: none;
  }
}

